	\"star\": {
		\"points\": 10,
		\"speed\": 180.0,
		\"color\": Color.YELLOW
	},
	\"gold_star\": {
		\"points\": 50,
		\"speed\": 260.0,
		\"color\": Color.ORANGE
	},
